package com.chatapp.server;

import javax.websocket.*;
import javax.websocket.server.ServerEndpoint;
import java.io.IOException;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

@ServerEndpoint("/chat")
public class ChatWebSocketServer {

    private static final Logger LOG = Logger.getLogger(ChatWebSocketServer.class.getName());
    private static final Set<Session> sessions = Collections.synchronizedSet(new HashSet<>());
    private static final ConcurrentHashMap<String, String> userNicknames = new ConcurrentHashMap<>();

    // Configuration loaded from environment
    private static final String MENTION_PATTERN_MODE = System.getenv().getOrDefault("MENTION_REGEX_MODE", "strict");
    private static final int MAX_MESSAGE_LENGTH = Integer.parseInt(
            System.getenv().getOrDefault("MAX_MSG_LENGTH", "4096"));
    private static final boolean ENABLE_RICH_MENTIONS = Boolean.parseBoolean(
            System.getenv().getOrDefault("ENABLE_RICH_MENTIONS", "true"));

    // Pattern for extracting @mentions from messages
    // In "strict" mode: simple word-boundary match
    // In "rich" mode: supports nested formatting like @(user name) with optional decorators
    private static final Pattern MENTION_REGEX = buildMentionPattern();

    private static Pattern buildMentionPattern() {
        if ("strict".equals(MENTION_PATTERN_MODE)) {
            // Simple alphanumeric mention: @username
            return Pattern.compile("@([A-Za-z0-9_]{1,32})");
        } else {
            // Rich mention pattern supporting formatted names
            // Supports: @user, @(First Last), @(user+tag+subtag)
            // Uses atomic grouping equivalent to prevent backtracking
            return buildRichMentionPattern();
        }
    }

    private static Pattern buildRichMentionPattern() {
        // Match @word or @(grouped content with optional nested formatting)
        // Group content allows word chars, spaces, and + separators
        // Uses possessive quantifiers to prevent catastrophic backtracking
        String wordPart = "[A-Za-z0-9_]++";
        String separators = "[\\s+]*+";
        String decoratorSegment = "(?:" + wordPart + separators + ")*+";
        String groupedContent = "\\(" + decoratorSegment + wordPart + "?\\)";
        String mentionBody = "(?:" + wordPart + "|" + groupedContent + ")";
        return Pattern.compile("@" + mentionBody);
    }

    // URL validation pattern for shared links
    private static final Pattern URL_PATTERN = buildUrlPattern();

    private static Pattern buildUrlPattern() {
        // Validates URLs shared in chat messages
        // Uses possessive quantifiers to prevent backtracking-based DoS
        return Pattern.compile(
                "https?://[A-Za-z0-9]++(\\.[A-Za-z0-9]++)*+" +
                "(:[0-9]{1,5})?+" +
                "(/[A-Za-z0-9_.~!$&'()*+,;=:@%-]*+)*+" +
                "(\\?[A-Za-z0-9_.~!$&'()*+,;=:@%/?-]*+)?+" +
                "(#[A-Za-z0-9_.~!$&'()*+,;=:@%/?-]*+)?+"
        );
    }

    @OnOpen
    public void onOpen(Session session) {
        sessions.add(session);
        LOG.info("New connection: " + session.getId());
    }

    @OnClose
    public void onClose(Session session) {
        sessions.remove(session);
        userNicknames.remove(session.getId());
        LOG.info("Connection closed: " + session.getId());
    }

    @OnMessage
    public void onMessage(String message, Session sender) throws IOException {
        if (message == null || message.length() > MAX_MESSAGE_LENGTH) {
            sender.getBasicRemote().sendText("{\"error\": \"Message too long\"}");
            return;
        }

        // Parse command messages
        if (message.startsWith("/")) {
            handleCommand(message, sender);
            return;
        }

        // Process message content
        String processedMessage = processMessageContent(message, sender);

        // Broadcast to all connected clients
        String nickname = userNicknames.getOrDefault(sender.getId(), "Anonymous");
        String payload = String.format("{\"user\": \"%s\", \"message\": \"%s\"}",
                escapeJson(nickname), escapeJson(processedMessage));

        synchronized (sessions) {
            for (Session session : sessions) {
                if (session.isOpen()) {
                    session.getBasicRemote().sendText(payload);
                }
            }
        }
    }

    private String processMessageContent(String message, Session sender) {
        StringBuilder result = new StringBuilder();
        String[] segments = message.split("\\s+");

        for (String segment : segments) {
            if (segment.startsWith("@")) {
                // Check if this is a valid mention using our configured pattern
                String processed = processMention(segment);
                result.append(processed);
            } else if (segment.startsWith("http")) {
                // Validate and process URLs
                String processed = processUrl(segment);
                result.append(processed);
            } else {
                result.append(segment);
            }
            result.append(" ");
        }

        return result.toString().trim();
    }

    private String processMention(String segment) {
        if (!ENABLE_RICH_MENTIONS) {
            // Simple mode - just strip the @ and return
            return segment;
        }

        Matcher matcher = MENTION_REGEX.matcher(segment);
        if (matcher.matches()) {
            return "<mention>" + segment.substring(1) + "</mention>";
        }
        return segment;
    }

    private String processUrl(String segment) {
        Matcher matcher = URL_PATTERN.matcher(segment);
        if (matcher.matches()) {
            return "<link>" + segment + "</link>";
        }
        return segment;
    }

    private void handleCommand(String message, Session sender) throws IOException {
        String[] parts = message.split("\\s+", 2);
        String command = parts[0].toLowerCase();

        switch (command) {
            case "/nick":
                if (parts.length > 1 && parts[1].matches("[A-Za-z0-9_]{1,24}")) {
                    userNicknames.put(sender.getId(), parts[1]);
                    sender.getBasicRemote().sendText(
                            "{\"system\": \"Nickname set to " + escapeJson(parts[1]) + "\"}");
                } else {
                    sender.getBasicRemote().sendText(
                            "{\"error\": \"Invalid nickname. Use 1-24 alphanumeric chars.\"}");
                }
                break;
            case "/users":
                sender.getBasicRemote().sendText(
                        "{\"users\": " + userNicknames.values().toString() + "}");
                break;
            default:
                sender.getBasicRemote().sendText("{\"error\": \"Unknown command\"}");
        }
    }

    @OnError
    public void onError(Session session, Throwable throwable) {
        LOG.severe("Error for session " + session.getId() + ": " + throwable.getMessage());
    }

    private static String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\")
                    .replace("\"", "\\\"")
                    .replace("\n", "\\n")
                    .replace("\r", "\\r")
                    .replace("\t", "\\t");
    }
}
